"""Command-line entry point: `harness <command>`."""

from pathlib import Path
from typing import Annotated

import typer

from harness.events import EVENTS_FILE
from harness.events import follow as follow_lines

app = typer.Typer(help="Plan-and-execute harness for Claude agents.", no_args_is_help=True)


def _not_implemented(name: str) -> None:
    typer.echo(f"harness {name}: not implemented yet", err=True)
    raise typer.Exit(code=1)


@app.command()
def run(plan: Path) -> None:
    """Run a plan."""
    _not_implemented("run")


@app.command()
def status() -> None:
    """Show task states for the current run."""
    _not_implemented("status")


@app.command()
def report() -> None:
    """Show tokens and cost per task and per tier."""
    _not_implemented("report")


@app.command()
def validate(plan: Path) -> None:
    """Validate a plan file."""
    _not_implemented("validate")


@app.command()
def events(
    run_dir: Path,
    follow: Annotated[bool, typer.Option("--follow", "-f", help="Keep printing.")] = False,
) -> None:
    """Print a run's event log (RUN_DIR/events.jsonl)."""
    path = run_dir / EVENTS_FILE
    if follow:
        for line in follow_lines(path):
            typer.echo(line)
        return
    if not path.exists():
        typer.echo(f"No event log at {path}", err=True)
        raise typer.Exit(code=1)
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.strip():
            typer.echo(line)

"""Load a plan file and check it: ids, dependencies, cycles, ownership, acceptance."""

import json
from pathlib import Path, PurePosixPath

from pydantic import ValidationError

from harness.models import Plan


class PlanError(ValueError):
    """The plan file is invalid. The message says why."""


def load_plan(path: Path) -> Plan:
    try:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
    except json.JSONDecodeError as err:
        raise PlanError(f"invalid JSON: {err}") from err
    try:
        plan = Plan.model_validate(data)
    except ValidationError as err:
        raise PlanError(f"invalid plan: {err}") from err
    validate_plan(plan)
    return plan


def validate_plan(plan: Plan) -> list[list[str]]:
    seen: set[str] = set()
    for order in plan.orders:
        if order.id in seen:
            raise PlanError(f"duplicate id: {order.id}")
        seen.add(order.id)

    for order in plan.orders:
        for dep in order.depends_on:
            if dep not in seen:
                raise PlanError(f"unknown dependency: {order.id} depends on {dep}")

    for order in plan.orders:
        if any(not cmd.strip() for cmd in order.acceptance):
            raise PlanError(f"empty acceptance: {order.id}")

    waves = compute_waves(plan)

    by_id = {o.id: o for o in plan.orders}
    for n, wave in enumerate(waves, start=1):
        owners: dict[str, str] = {}
        for oid in wave:
            for p in by_id[oid].files_owned:
                key = str(PurePosixPath(p))
                if key in owners:
                    raise PlanError(
                        f"overlapping files_owned in wave {n}: {key} ({owners[key]}, {oid})"
                    )
                owners[key] = oid
    return waves


